                    },
                ),
                LogEntry::turn_complete(now, 1, "echoed: hello".into(), 1),
            ],
        );

        let history = session.replay_history().expect("replay");
        // user + assistant(tool call) + tool result + assistant(text) = 4
        assert_eq!(history.len(), 4);
